package com.rdforward.protocol;

import java.util.Map;
import java.util.List;
import java.util.Arrays;

public final class TextUtil {
    public static final String KICK = "Conection lost";
    public static String stripColor(String s) { String tmp = s.replaceAll("\u00a7.", ""); return tmp; }
    public static boolean isBlank(String s) { return s.trim().isEmpty() == true; }
    public static String firstWord(String s) { return s.split(" ")[0]; }
    public static <T> List<T> lastN(List<T> a, int n) { return a.subList(a.size() - n - 1, a.size()); }
    public static List<String> splitLines(String s) { return Arrays.asList(s.split("\n")); }
    public static String clip(String s) { return s.length() > 256 ? s.substring(0, 256) : s; }
}
